declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-knowledge.php';require_once __DIR__.'/app/research-intelligence.php';require_once __DIR__.'/app/research-entities.php';require_once __DIR__.'/app/ai.php';require_once __DIR__.'/app/ai-access.php';require_once __DIR__.'/app/research-workspace.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$project=project_access($pdo,(int)$u['id'],$id);if(!$project){http_response_code(404);exit('Research project not found.');}$canWrite=project_can_write($project);$success='';$error='';$aiAnswer='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='create_claim'){
        $statement=trim((string)($_POST['statement']??''));if($statement==='')throw new RuntimeException('Claim statement is required.');
        $type=(string)($_POST['claim_type']??'factual');if(!in_array($type,['factual','disputed','prediction','interpretation','data_point'],true))$type='factual';
        $public=ulid_like();$pdo->prepare('INSERT INTO research_claims(public_id,project_id,created_by_user_id,statement,claim_type) VALUES(?,?,?,?,?)')->execute([$public,$project['id'],$u['id'],$statement,$type]);if(research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$project['id'],3);header('Location:/research-claim.php?id='.rawurlencode($public));exit;
    }
    if($op==='create_finding'){
        $title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));if($title===''||$summary==='')throw new RuntimeException('Finding title and summary are required.');
        $public=ulid_like();$pdo->prepare('INSERT INTO research_findings(public_id,project_id,created_by_user_id,title,summary) VALUES(?,?,?,?,?)')->execute([$public,$project['id'],$u['id'],$title,$summary]);if(research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$project['id'],3);header('Location:/research-finding.php?id='.rawurlencode($public));exit;
    }
    if($op==='ask_ai'){
        if(!user_is_pro($pdo,$u))throw new RuntimeException('Knowledge synthesis is available to Pro users.');$isAdmin=($u['role']??'')==='admin';$quota=rate_limit_consume($pdo,$isAdmin?'ai-admin':'ai-pro','user:'.(string)$u['id'],$isAdmin?240:40,3600);if(!$quota['allowed'])throw new RuntimeException('AI request limit reached. Try again later.');
        $question=trim((string)($_POST['question']??''));if($question==='')throw new RuntimeException('Ask a research question.');$model=ai_setting_model_id($pdo,'research',true);if(!$model)$model=ai_setting_model_id($pdo,'pro',true);if(!$model)throw new RuntimeException('No Pro research model is configured.');ai_interactive_model_record($pdo,$u,$model);
        $base=ai_research_context($pdo,(int)$project['id']);$knowledge=research_knowledge_ai_context($pdo,(int)$project['id']);$intel=research_intelligence_ai_context($pdo,(int)$project['id']);$entities=research_entity_graph_ai_context($pdo,(int)$project['id']);
        $system='You are Ask Annotated, a provenance-first research assistant. Use only supplied project context. Distinguish captured evidence from human-authored Claims, Findings, Claim relationships, Entities, and Entity relationships. Cite exact IDs as [SOURCE id], [ANNOTATION id], [CLAIM id], [FINDING id], [CLAIM-RELATION id], [ENTITY id], or [ENTITY-RELATION id]. Treat Claim status as a human research state, not proof. Treat Entity status=suggested as unconfirmed extraction, not fact. Entity and Claim graph relationships are authored research structure, not independent evidence. Identify contradictions and missing evidence. Never invent citations or silently convert inference into fact.';
        $prompt="Project: {$project['title']}\nQuestion: {$question}\n\nSOURCE AND ANNOTATION CONTEXT:\n{$base['text']}\n\nSTRUCTURED KNOWLEDGE CONTEXT:\n{$knowledge['text']}\n\nCLAIM GRAPH AND PROJECT SNAPSHOT:\n{$intel['text']}\n\nENTITY KNOWLEDGE GRAPH:\n{$entities['text']}";
        $r=ai_run($pdo,$config,$u,$isAdmin?'admin':'pro','research_knowledge_question',$model,$system,$prompt,array_merge($base['refs'],$knowledge['refs'],$intel['refs'],$entities['refs'],[['type'=>'question','text'=>$question]]),'research_project',$project['public_id']);$aiAnswer=$r['text'];
    }
}catch(Throwable $e){$error=$e->getMessage();}}
$q=$pdo->prepare("SELECT rc.*,u2.display_name,(SELECT COUNT(*) FROM claim_evidence ce WHERE ce.claim_id=rc.id) evidence_count FROM research_claims rc JOIN users u2 ON u2.id=rc.created_by_user_id WHERE rc.project_id=? ORDER BY FIELD(rc.status,'disputed','contradicted','unverified','supported','resolved'),rc.updated_at DESC");$q->execute([$project['id']]);$claims=$q->fetchAll();
$q=$pdo->prepare("SELECT rf.*,u2.display_name,(SELECT COUNT(*) FROM finding_claims fc WHERE fc.finding_id=rf.id) claim_count FROM research_findings rf JOIN users u2 ON u2.id=rf.created_by_user_id WHERE rf.project_id=? ORDER BY FIELD(rf.status,'draft','final','archived'),rf.updated_at DESC");$q->execute([$project['id']]);$findings=$q->fetchAll();
$claimCounts=array_fill_keys(['unverified','supported','disputed','contradicted','resolved'],0);foreach($claims as $c)$claimCounts[$c['status']]++;
