<h2>Claims</h2><?php if(!$claims):?><div class="card empty">No Claims yet. Claims are structured statements that can carry supporting, contradicting, contextual, and primary evidence.</div><?php endif?><?php foreach($claims as $c):?><article class="card"><div class="meta"><?=h(strtoupper($c['claim_type']))?> · <?=h(strtoupper($c['status']))?> · <?=h((string)$c['evidence_count'])?> evidence · <?=h($c['display_name'])?></div><h3><a href="/research-claim.php?id=<?=h($c['public_id'])?>"><?=h($c['statement'])?></a></h3><?php if($c['resolution_note']):?><p><?=nl2br(h($c['resolution_note']))?></p><?php endif?></article><?php endforeach?>
<h2>Findings</h2><?php if(!$findings):?><div class="card empty">No Findings yet. Findings synthesize multiple Claims into a project-level conclusion.</div><?php endif?><?php foreach($findings as $f):?><article class="card"><div class="meta"><?=h(strtoupper($f['status']))?> · <?=h((string)$f['claim_count'])?> claims · <?=h($f['display_name'])?></div><h3><a href="/research-finding.php?id=<?=h($f['public_id'])?>"><?=h($f['title'])?></a></h3><p><?=nl2br(h(mb_substr((string)$f['summary'],0,600)))?></p></article><?php endforeach?></section><aside><?php if($canWrite):?><div class="card"><h3>New Claim</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="create_claim"><label>Statement<textarea name="statement" rows="5" required placeholder="State the claim precisely."></textarea></label><label>Type<select name="claim_type"><option value="factual">Factual</option><option value="disputed">Disputed</option><option value="prediction">Prediction</option><option value="interpretation">Interpretation</option><option value="data_point">Data point</option></select></label><button>Create Claim</button></form></div><div class="card"><h3>New Finding</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="create_finding"><label>Title<input name="title" required placeholder="Finding title"></label><label>Summary<textarea name="summary" rows="6" required placeholder="What does the assembled evidence show?"></textarea></label><button>Create Finding</button></form></div><?php endif?><div class="card"><h3>Research Intelligence</h3><p><a href="/research-brief.php?id=<?=h($project['public_id'])?>">Research Brief →</a></p><p><a href="/research-timeline.php?id=<?=h($project['public_id'])?>">Research Timeline →</a></p><p><a href="/research-graph.php?id=<?=h($project['public_id'])?>">Claim Graph →</a></p><p><a href="/research-entities.php?id=<?=h($project['public_id'])?>">Entity Graph →</a></p></div><div class="card"><h3>Ask Knowledge</h3><?php if($canWrite&&user_is_pro($pdo,$u)):?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="ask_ai"><textarea name="question" rows="5" required placeholder="Which Claims, entities, relationships or evidence gaps matter most?"></textarea><button>Ask Annotated</button></form><?php else:?><p class="meta">Available to Pro project writers. Answers are scoped to this project's Sources, Annotations, Claims, Findings, Claim Graph and Entity Graph.</p><?php endif?></div><div class="card"><h3>Knowledge model</h3><p class="meta">Source Version → Annotation → Claim → Evidence relationship → Claim Graph → Finding → Entities/Entity Graph → Research Brief. Project permissions apply to every object.</p></div></aside></main></body></html>
